def score(program: str) -> float:
    defs = program.count('def ')
    classes = program.count('class ')
    control = program.count('if ') + program.count('for ') + program.count('while ')
    score = (defs * 0.92 + classes * 1.30 + control * 0.45) / 13.2
    return min(max(score, 0), 1)

